#!/usr/bin/env dotnet
#:property AllowUnsafeBlocks=true

Console.WriteLine($"IntPtr.Size = {IntPtr.Size} bytes");

// stackalloc a Span of native-sized integers (nint)
Span<nint> nints = stackalloc nint[4];
for (int i = 0; i < nints.Length; i++)
    nints[i] = i * 10;

Console.WriteLine("Span<nint> via stackalloc:");
foreach (var v in nints)
    Console.WriteLine($"  {v}");

// Also test nuint (unsigned native-sized integer)
Span<nuint> nuints = stackalloc nuint[3];
nuints[0] = 100;
nuints[1] = 200;
nuints[2] = 300;

Console.WriteLine("Span<nuint> via stackalloc:");
foreach (var v in nuints)
    Console.WriteLine($"  {v}");

Console.WriteLine("Success — stackalloc with nint/nuint works!");

